wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// Key under which the node records the input of its most recent call.
/// `state-rw` is imported per the approved grant extension; if the host does
/// not yet provide it, instantiation will fail until the graph is updated.
const LAST_INPUT_KEY: &str = "last-input";

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input received on this call in the shared store.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: one fetch. A transport failure is a value and counts as
        // zero characters; a request outside the allowlist traps at the host.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message carries only values this node computed, never
        // the fetched (untrusted) body.
        let message = format!(
            "heartbeat: time={}s fetched={} chars",
            seconds, fetched
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // Contract: ensures notified == true. If the channel never accepted
        // the notification, trap rather than emit a report that violates the
        // contract or falsely claims delivery.
        if !notified {
            panic!("heartbeat notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

